import * as React from "react";
import { ArrowRight, BookOpen, Github } from "lucide-react";
import { NavLink } from "../../../components/NavLink";
import { Button } from "../../../components/ui/button";
import type { FontLibrary } from "../../fonts/useFontLibrary";
import { displayName } from "../../fonts/metadata";
import { FontCanvas } from "../../renderer/FontCanvas";
import { defaultVariantSettings } from "../../variants/model";
import { SiteHeader } from "../../shell/SiteHeader";
import { libraryPalette } from "../library/canvas-palettes";
import "./LandingPage.css";

const SOURCE = "https://github.com/ai212983/font_generator";

interface LandingPageProps {
  nav: React.ReactNode;
  fontsHref: string;
  onFonts: () => void;
  library: FontLibrary;
}

export function LandingPage({ nav, fontsHref, onFonts, library }: LandingPageProps): React.JSX.Element {
  const font = library.fonts?.find((item) => item.fileName === "Literata.ttf") ?? library.fonts?.[0];
  const settings = font ? defaultVariantSettings(font) : null;
  const { ensureLoaded } = library;
  const fontId = font?.id;
  React.useEffect(() => {
    if (fontId) ensureLoaded(fontId);
  }, [ensureLoaded, fontId]);
  const [renderError, setRenderError] = React.useState("");
  React.useEffect(() => setRenderError(""), [fontId]);
  const ready = Boolean(fontId && library.loadedIds.has(fontId));
  const unavailable = library.rendererAvailable === false || Boolean(renderError || (fontId && library.loadStatus(fontId).error));

  return (
    <div className="landing">
      <SiteHeader title="Glypherie" titleAs="div" variant="brand" nav={nav} displayControls={false} />
      <main id="main" className="landing__main" data-landing>
        <section className="landing__hero" aria-labelledby="landing-title">
          <div>
            <p className="landing__eyebrow">A playground for small type</p>
            <h1 id="landing-title">Small type.<br /><span>Big possibilities.</span></h1>
            <p className="landing__intro">
              Explore how fonts look when every pixel counts. Bring your own type,
              tune its rendering and make bitmap fonts right in your browser.
            </p>
            <div className="landing__actions">
              <Button asChild size="lg">
                <NavLink href={fontsHref} onNavigate={onFonts}>Open font library <ArrowRight aria-hidden="true" /></NavLink>
              </Button>
              <a href={`${SOURCE}#documentation`} className="landing__text-link"><BookOpen aria-hidden="true" />Documentation</a>
            </div>
            <p className="landing__note">No account needed. Your fonts stay in your browser.</p>
          </div>
          <figure className="landing__specimen" aria-label="Live monochrome font specimen">
            <div className="landing__specimen-heading"><span>From type to pixels</span><span aria-hidden="true">Aa / 01</span></div>
            <div className="landing__specimen-body">
              {font && settings && !unavailable ? (
                <FontCanvas
                  key={font.id}
                  fontId={font.id}
                  text={"Aa Bb\n012345"}
                  sizePx={24}
                  axes={settings.axes}
                  profile={settings.profile}
                  role={settings.renderer}
                  spacing={settings.letterSpacingPx}
                  kerning={settings.kerning}
                  stemFitting={settings.stemFitting}
                  diagonalFitting={settings.diagonalFitting}
                  monoRaster={settings.monoRaster}
                  rasterization="free_type_mono"
                  zoom={3}
                  mode="exact"
                  palette={libraryPalette("warm-paper", false)}
                  ready={ready}
                  debounceMs={0}
                  viewportProps={{ className: "landing__canvas", "aria-hidden": true }}
                  canvasProps={{ "data-landing-canvas": "", className: "block [image-rendering:pixelated]" }}
                  exposeFullHeight
                  clearOnError
                  onError={setRenderError}
                />
              ) : <span className="landing__type" aria-hidden="true">Aa</span>}
              {!ready && !unavailable && <span className="landing__specimen-status">Preparing the live specimen…</span>}
            </div>
            <figcaption>
              <span>{font && !unavailable ? displayName(font) : "Your next font starts here"}</span>
              <span>{font && !unavailable ? "24 px · Monochrome · 3× view" : "Explore the font library"}</span>
            </figcaption>
          </figure>
        </section>

        <section className="landing__workflow" aria-labelledby="landing-start">
          <div className="landing__section-heading"><p className="landing__eyebrow">A few steps, plenty to explore</p><h2 id="landing-start">Bring a font. Make it yours.</h2></div>
          <ol className="landing__steps">
            <li><span className="landing__step-number">01</span><h3>Pick your type</h3><p>Start with the bundled fonts or import a .ttf or .otf file into your library.</p></li>
            <li><span className="landing__step-number">02</span><h3>Find your pixels</h3><p>Create a variant. Adjust size, variable axes and spacing, then explore monochrome or grayscale rendering.</p></li>
            <li><span className="landing__step-number">03</span><h3>Keep what works</h3><p>Save variants in your browser. Export a monochrome bitmap font for Playdate when you’re ready.</p></li>
          </ol>
        </section>

        <section className="landing__details" aria-label="About the project">
          <div><h2>Your fonts, locally.</h2><p>Fonts, saved variants and palette presets live in this browser on this device. They aren’t uploaded or synced. Clearing site data removes your library; a saved variant link needs that same local library.</p></div>
          <div><h2>Open source. Open to exploration.</h2><p>Glypherie is a workspace for font research and glyph generation. Explore the project, read the documentation or look under the hood.</p><a href={SOURCE} className="landing__text-link"><Github aria-hidden="true" />View source on GitHub <ArrowRight aria-hidden="true" /></a></div>
        </section>
      </main>
    </div>
  );
}
